def get_dpk_product():
    # Core Banking Data
    dpk_used_cols = getConfig('product_data_preprocessing', 'dpk_used_cols')
    db = 'dm_analytics'
    table = 'dm_dpk'
    queries = "SELECT {} FROM {}.{}".format(','.join(dpk_used_cols), db, table)
    df_dpk = spark.sql(queries)  # OPEN / TO BE VALIDATED: Unity Catalog names for dm_analytics.dm_dpk (K7 tables, K4-TBL-004)

    coln = 'report_date'
    df_dpk = df_dpk.withColumn(coln, df_dpk[coln].cast('bigint').cast('string'))
    df_dpk = df_dpk.withColumn(coln, F.to_date(coln, format='yyyyMMdd'))
    df_dpk = df_dpk.withColumn(coln, df_dpk[coln].cast('string'))

    coln = 'account_open_date'
    df_dpk = df_dpk.withColumn(coln, F.to_date(df_dpk[coln], 'yyyy/MM/dd HH:mm:ss'))
    df_dpk = df_dpk.withColumn(coln, df_dpk[coln].cast('string'))

    # filter akun yang dibuka
    df_dpk = df_dpk.filter(F.col('account_open_date') <= max_date)

    # filter report_date
    df_dpk = df_dpk.filter(F.col('report_date') <= max_date)

    df_dpk = df_dpk.withColumn('max_report_date', F.max('report_date').over(Window.partitionBy('account_number')))
    df_dpk = df_dpk.withColumn('close_status', F.when(F.col('max_report_date') < F.col('max_date'), F.lit(1)).otherwise(0))
    df_dpk = df_dpk.withColumn('account_close_date', F.when(F.col('close_status') == 1, F.col('max_report_date')).otherwise(None))
    df_dpk = df_dpk.drop('max_report_date', 'max_date')

    col_list = ['category_group', 'category_desc', 'currency']
    for coln in col_list:
        df_dpk = clean_text(df_dpk, coln)

    sel_prod = ['rek sinas dana investor personal', 'az time deposit', 'az call deposit 1 day']
    for prod in sel_prod:
        df_dpk = df_dpk.withColumn(
            'category_desc',
            F.when(
                (F.col('category_desc') == prod),
                F.concat(df_dpk['category_desc'], F.lit(' '), df_dpk['currency'])
            ).otherwise(df_dpk['category_desc'])
        )

    df_dpk = df_dpk.drop('report_date', 'currency', 'close_status')
    df_dpk = df_dpk.drop_duplicates()
    df_dpk = df_dpk.repartition('cif_number')

    core_banking_cust = df_customer.join(df_dpk, on='cif_number', how='inner')
    core_banking_cust = core_banking_cust.withColumnRenamed('category_desc', 'product')
    core_banking_cust = core_banking_cust.drop_duplicates()
    return core_banking_cust


def get_banca_product():
    banca_used_cols = getConfig('product_data_preprocessing', 'banca_used_cols')
    db = 'dm_analytics'
    table = 'dm_banca_aum_summary'
    queries = "SELECT {} FROM {}.{}".format(", ".join(banca_used_cols), db, table)
    df_banca = spark.sql(queries)  # OPEN / TO BE VALIDATED: Unity Catalog names for dm_analytics.dm_banca_aum_summary (K7 tables, K4-TBL-004)
    df_banca = df_banca.withColumnRenamed('cif_number_by_disburse_account', 'cif_number')

    coln = 'report_date'
    df_banca = df_banca.withColumn(coln, F.to_date(coln, format='yyyyMMdd'))
    df_banca = df_banca.withColumn(coln, df_banca[coln].cast('string'))

    coln = 'pinbook_date'
    df_banca = df_banca.withColumn(coln, F.to_date(coln, format='yyyyMMdd'))
    df_banca = df_banca.withColumn(coln, df_banca[coln].cast('string'))
    df_banca = df_banca.withColumnRenamed('pinbook_date', 'account_open_date')

    # filter akun yang dibuka
    df_banca = df_banca.filter(F.col('account_open_date') <= max_date)
    df_banca = df_banca.filter(F.col('account_open_date') != '2000-01-01')

    # filter report_date
    df_banca = df_banca.filter(F.col('report_date') <= max_date)

    df_banca = df_banca.withColumn(
        'max_report_date',
        F.max('report_date').over(Window.partitionBy('policy_no'))
    )
    df_banca = df_banca.filter(F.col('report_date') == F.col('max_report_date'))
    df_banca = df_banca.withColumn('max_date', F.max('report_date').over(Window.partitionBy()))
    df_banca = df_banca.withColumn(
        'close_status',
        F.when(F.col('max_report_date') < F.col('max_date'), F.lit(1)).otherwise(0)
    )
    df_banca = df_banca.withColumn(
        'account_close_date',
        F.when(F.col('close_status') == 1, F.col('max_report_date')).otherwise(None)
    )
    df_banca = df_banca.drop('report_date', 'close_status', 'max_report_date', 'max_date')

    coln = 'product_name'
    df_banca = clean_text(df_banca, coln)
    df_banca = df_banca.repartition('cif_number')

    banca_cust = df_customer.join(df_banca, on='cif_number', how='inner')
    banca_cust = banca_cust.withColumnRenamed('product_name', 'product')
    banca_cust = banca_cust.withColumn('category_group', F.lit('bancassurance'))
    banca_cust = banca_cust.withColumnRenamed('policy_no', 'account_number')
    banca_cust = banca_cust.drop_duplicates()
    return banca_cust


