    df_cc = spark.sql(queries)  # OPEN / TO BE VALIDATED: Unity Catalog names for dm_analytics.dm_cc_portfolio (K7 tables, K4-TBL-004)
    df_cc = clean_text(df_cc, 'cif_number')
    df_cc = df_cc.withColumn('loc_acct', F.col('loc_acct').cast('bigint').cast('string'))
