    coln = 'report_date'
    df_cc = df_cc.withColumn(coln, df_cc[coln].cast('bigint').cast('string'))
    df_cc = df_cc.withColumn(coln, F.to_date(coln, format='yyyyMMdd'))
    df_cc = df_cc.withColumn(coln, df_cc[coln].cast('string'))

    coln = 'cncl_dt'
