    table = 'dm_cc_card'
    queries = "SELECT {} FROM {}.{}".format(", ".join(ccc_used_cols), db, table)
    df_ccc = spark.sql(queries)  # OPEN / TO BE VALIDATED: Unity Catalog names for dm_analytics.dm_cc_card (K7 tables, K4-TBL-004)
    df_ccc = df_ccc.withColumn('loc_acct', F.col('loc_acct').cast('bigint').cast('string'))
