    coln = 'card_anv_dt'
    df_ccc = df_ccc.withColumn(coln, F.col(coln).cast('bigint').cast('string'))
    df_ccc = df_ccc.withColumn(coln, F.to_date(df_ccc[coln], 'yyyyMMdd'))
    df_ccc = df_ccc.withColumn(coln, df_ccc[coln].cast('string'))
    df_ccc = df_ccc.withColumnRenamed(coln, 'account_open_date')

