def get_loan_product():
    # Loan Data
    loan_used_cols = getConfig('product_data_preprocessing', 'loan_used_cols')
    db = 'dm_analytics'
    table = 'dm_loan'
    queries = "SELECT {} FROM {}.{}".format(','.join(loan_used_cols), db, table)
    df_loan = spark.sql(queries)  # OPEN / TO BE VALIDATED: Unity Catalog names for dm_analytics.dm_loan (K7 tables, K4-TBL-004)
    df_loan = df_loan.repartition('contract_no')

    used_cols = ['custcode', 'payment_date', 'payment_status']
    db = 'dm_analytics'
    table = 'dm_skala_rental_tab'
    queries = "SELECT {} FROM {}.{}".format(','.join(used_cols), db, table)
    df_srt = spark.sql(queries)  # OPEN / TO BE VALIDATED: Unity Catalog names for dm_analytics.dm_skala_rental_tab (K7 tables, K4-TBL-004)
    df_srt = df_srt.drop_duplicates()

    coln = 'payment_date'
    df_srt = df_srt.withColumn(coln, F.split(F.col(coln), ' ').getItem(0))
    df_srt = df_srt.withColumn(coln, F.to_date(coln, format='dd-MMM-yy'))
    df_srt = df_srt.withColumn(coln, df_srt[coln].cast('string'))
    df_srt = df_srt.filter(F.col(coln) <= max_date)

    df_srt = df_srt.withColumn('max_' + coln, F.max(coln).over(Window.partitionBy('custcode')))
    df_srt = df_srt.filter(F.col(coln) == F.col('max_' + coln))
    df_srt = df_srt.drop('max_' + coln)

    coln = 'payment_status'
    df_srt = df_srt.withColumn('payment_date', F.when(F.col(coln) == 4.0, F.col('payment_date')).otherwise(None))
    df_srt = df_srt.withColumn(coln, F.when(F.col(coln) == 4.0, F.lit(1)).otherwise(0))
    df_srt = df_srt.withColumnRenamed('custcode', 'contract_no')
    df_srt = df_srt.withColumnRenamed('payment_date', 'account_close_date')
    df_srt = df_srt.drop('payment_status')
    df_srt = df_srt.drop_duplicates()
    df_srt = df_srt.repartition('contract_no')

    coln = 'report_date'
    df_loan = df_loan.withColumn(coln, df_loan[coln].cast('bigint').cast('string'))
    df_loan = df_loan.withColumn(coln, F.to_date(coln, format='yyyyMMdd'))
    df_loan = df_loan.withColumn(coln, df_loan[coln].cast('string'))

    coln = 'tanggal_awal'
    df_loan = df_loan.withColumn(coln, F.to_date(df_loan[coln], 'yyyy/MM/dd HH:mm:ss'))
    df_loan = df_loan.withColumn(coln, df_loan[coln].cast('string'))
    df_loan = df_loan.withColumnRenamed('tanggal_awal', 'account_open_date')

    # filter akun yang dibuka
    df_loan = df_loan.filter(F.col('account_open_date') <= max_date)

    # filter akun report date
    df_loan = df_loan.filter(F.col('report_date') <= max_date)
    df_loan = df_loan.withColumn('max_report_date', F.max('report_date').over(Window.partitionBy('cif', 'contract_no')))
    df_loan = df_loan.filter(F.col('report_date') == F.col('max_report_date'))
    df_loan = df_loan.drop('max_report_date', 'report_date')

    df_loan = df_loan.join(df_srt, on='contract_no', how='left')

    coln = 'type_of_financing'
    df_loan = clean_text(df_loan, coln)

    df_loan = df_loan.withColumnRenamed('cif', 'cif_number')
    df_loan = df_loan.repartition('cif_number')
    df_loan = df_loan.join(df_customer, on='cif_number', how='inner')
    df_loan = df_loan.withColumnRenamed('type_of_financing', 'product')
    df_loan = df_loan.withColumnRenamed('contract_no', 'account_number')
    df_loan = df_loan.withColumn('category_group', F.lit('consumer loan'))

    loan_journey = df_loan.withColumn(
        'loan_credit_facility',
        F.when(F.col('fasilitas_kredit').contains('smf'), F.lit('smf'))
        .otherwise(F.when(F.col('fasilitas_kredit').contains('danamas'), F.lit('danamas'))
                   .otherwise('general loan'))
    )
    loan_journey = loan_journey.select('cif_number', 'loan_credit_facility', 'account_open_date')
    loan_journey = loan_journey.drop_duplicates()
    loan_journey = loan_journey.repartition('cif_number')

    w = Window().partitionBy('cif_number').orderBy(F.asc('account_open_date'))
    loan_journey = loan_journey.withColumn('rn', F.row_number().over(w)).where(F.col('rn') == 1).drop('rn')
    loan_journey = loan_journey.drop('account_open_date')

    writeData(loan_journey, spark, 'mldb', 'mii_rs_loan_journey')

    df_loan = df_loan.drop('fasilitas_kredit')
    return df_loan, loan_journey


def get_reksadana_product():
    reksa_used_cols = getConfig('product_data_preprocessing', 'reksa_used_cols')
    db = 'dm_analytics'
    table = 'dm_reksadana'
    queries = "SELECT {} FROM {}.{}".format(", ".join(reksa_used_cols), db, table)
    df_reksa = spark.sql(queries)  # OPEN / TO BE VALIDATED: Unity Catalog names for dm_analytics.dm_reksadana (K7 tables, K4-TBL-004)
    df_reksa = df_reksa.withColumnRenamed('ifua', 'account_number')
    df_reksa = df_reksa.repartition('account_number')

    coln = 'report_date'
    df_reksa = df_reksa.withColumn(coln, F.to_date(coln, format='yyyyMMdd'))
    df_reksa = df_reksa.withColumn(coln, df_reksa[coln].cast('string'))

    coln = 'holding_date'
    df_reksa = df_reksa.withColumn(coln, F.to_date(coln, format='yyyyMMdd'))
    df_reksa = df_reksa.withColumn(coln, df_reksa[coln].cast('string'))
    df_reksa = df_reksa.withColumn('account_open_date', F.min(coln).over(Window.partitionBy('cif', 'account_number')))
    df_reksa = df_reksa.drop(coln)

    # filter akun yang dibuka
    df_reksa = df_reksa.filter(F.col('account_open_date') <= max_date)

    # filter akun report date
    df_reksa = df_reksa.filter(F.col('report_date') <= max_date)

    # get account_close_date
    tmp = df_reksa.select('report_date', 'account_number', 'jumlah_unit')
    w = Window.partitionBy('account_number').orderBy('report_date')

    tmp = tmp.withColumn('id', F.row_number().over(w))
    tmp = tmp.filter(F.col('jumlah_unit') == 0)
    tmp = tmp.withColumn('prev_id', F.lag('id').over(w))
    tmp = tmp.withColumn('diff', F.when(F.isNull(F.col('id') - F.col('prev_id')), F.lit(0)).otherwise(F.col('id') - F.col('prev_id')))
    tmp = tmp.filter(F.col('diff') > 1)
    w = Window.partitionBy('account_number')
    tmp = tmp.withColumn('account_close_date', F.max('report_date').over(w))
    tmp = tmp.filter(F.col('report_date') == F.col('account_close_date'))

    tmp = tmp.drop('id', 'prev_id', 'diff', 'report_date', 'jumlah_unit')
    tmp = tmp.drop_duplicates()
    tmp = tmp.repartition('account_number')

    df_reksa = df_reksa.withColumn('max_report_date', F.max('report_date').over(Window.partitionBy('cif', 'account_number')))
    df_reksa = df_reksa.filter(F.col('report_date') == F.col('max_report_date'))
    df_reksa = df_reksa.drop('max_report_date', 'report_date')

    df_reksa = df_reksa.join(tmp, on='account_number', how='left')
    df_reksa = df_reksa.withColumn('account_close_date', F.when(F.col('jumlah_unit') == 0, F.col('account_close_date')).otherwise(F.lit(None)))
    df_reksa = df_reksa.drop('jumlah_unit')

    coln = 'category_name'
    df_reksa = clean_text(df_reksa, coln)

    df_reksa = df_reksa.withColumnRenamed('open_date', 'account_open_date')
    df_reksa = df_reksa.drop_duplicates()

    df_reksa = df_reksa.withColumnRenamed('cif', 'cif_number')
    reksa_cust = df_customer.join(df_reksa, on='cif_number', how='inner')
    reksa_cust = reksa_cust.withColumnRenamed('category_name', 'product')
    reksa_cust = reksa_cust.withColumn('category_group', F.lit('reksadana'))
    return reksa_cust


if __name__ == '__main__':
    core_banking_cust = get_dpk_product()
    banca_cust = get_banca_product()
    cc_cust = get_cc_product()
    loan_cust, loan_journey = get_loan_product()
    reksa_cust = get_reksadana_product()

    # Union all customers
    dataset = core_banking_cust.unionByName(banca_cust)
    dataset = dataset.unionByName(cc_cust)
    dataset = dataset.unionByName(loan_cust)
    dataset = dataset.unionByName(reksa_cust)

    # Get Customer Journey
    dataset = dataset.repartition('cif_number')
    w = Window.partitionBy('cif_number')
    tmp = dataset.withColumn('min_open_date', F.min('account_open_date').over(w))
    tmp = tmp.filter(F.col('account_open_date') == F.col('min_open_date'))
    cust_journey = tmp.groupBy('cif_number').agg(F.collect_set('category_group').alias('product'))
    cust_journey = cust_journey.withColumn(
        'journey',
        F.when(F.array_contains(F.col('product'), 'consumer loan'), F.lit('loan'))
        .otherwise(F.when(F.array_contains(F.col('product'), 'tabungan'), F.lit('tabungan'))
                   .otherwise('others'))
    )
    cust_journey = cust_journey.drop('product')
    cust_journey = cust_journey.join(loan_journey.select('cif_number', 'loan_credit_facility'), on='cif_number', how='left')
    cust_journey = cust_journey.withColumn(
        'journey',
        F.when(F.col('loan_credit_facility') == 'smf', F.lit('loan')).otherwise(F.col('journey'))
    )
    cust_journey = cust_journey.drop('loan_credit_facility')

    writeData(cust_journey, spark, 'mldb', 'mii_rs_customer_journey')

    cond = [dataset['product'] == product_list['product_name_on_data']]
    dataset = dataset.join(F.broadcast(product_list.select('product_name_on_data', 'biu')), cond, how='inner')
    dataset = dataset.drop('product_name_on_data')
    dataset = dataset.drop_duplicates()

    # Write data to hive
    dataset = dataset.withColumn('training_date', F.lit(today.strftime('%Y-%m-%d')))

    writeData(dataset, spark, 'mldb', 'mii_rs_product_portfolio', partition='training_date')

    pass  # removed by ws4conv (K4-SPK-006): do not stop the shared session on Databricks
